#!/usr/bin/env python3
from __future__ import annotations

import argparse
import os
import shutil
import subprocess
import sys
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent

SOURCE_SUFFIXES = (".ixx", ".cppm", ".cpp", ".cc", ".cxx", ".h", ".hpp", ".hh", ".hxx")

# protoc output carries "DO NOT EDIT" and is regenerated by generate_protocol.py.
GENERATED_SUFFIXES = (".pb.h", ".pb.cc")

SKIPPED_DIR_NAMES = {"obj", "bin", "build", ".xmake", ".vs", ".idea", "vsxmake2026"}


def iter_ancestor_dirs(start: Path):
    current = start.resolve()
    if current.is_file():
        current = current.parent

    while True:
        yield current
        if current.parent == current:
            break
        current = current.parent


def find_repo_root(explicit: str | None) -> Path:
    if explicit:
        repo_root = Path(explicit).expanduser().resolve()
        if not (repo_root / "xmake.lua").is_file():
            raise FileNotFoundError(f"xmake.lua not found in repo root: {repo_root}")
        return repo_root

    seen: set[Path] = set()
    for start in (Path.cwd(), SCRIPT_DIR):
        for candidate in iter_ancestor_dirs(start):
            if candidate in seen:
                continue
            seen.add(candidate)
            if (candidate / "xmake.lua").is_file():
                return candidate

    raise FileNotFoundError(
        "Could not find repo root.\n"
        "Expected to find xmake.lua in the current directory, one of its parents,\n"
        "or one of the parent directories of this script.\n"
        "Use --repo-root to specify it explicitly."
    )


def find_clang_format(explicit: str | None) -> Path:
    if explicit:
        path = Path(explicit).expanduser().resolve()
        if not path.is_file():
            raise FileNotFoundError(f"clang-format not found: {path}")
        return path

    from_env = os.environ.get("CLANG_FORMAT")
    if from_env:
        path = Path(from_env).expanduser().resolve()
        if path.is_file():
            return path

    from_path = shutil.which("clang-format")
    if from_path:
        return Path(from_path).resolve()

    # Visual Studio ships clang-format with its optional LLVM component.
    vswhere = Path(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)")) / "Microsoft Visual Studio" / "Installer" / "vswhere.exe"
    if vswhere.is_file():
        result = subprocess.run(
            [str(vswhere), "-latest", "-products", "*", "-property", "installationPath"],
            capture_output=True,
            text=True,
            check=False,
        )
        for line in result.stdout.splitlines():
            candidate = Path(line.strip()) / "VC" / "Tools" / "Llvm" / "x64" / "bin" / "clang-format.exe"
            if candidate.is_file():
                return candidate

    raise FileNotFoundError(
        "clang-format not found.\n"
        "Put it on PATH, set CLANG_FORMAT, or pass --clang-format explicitly."
    )


def is_skipped(path: Path, root: Path) -> bool:
    relative_parts = path.relative_to(root).parts[:-1]
    if any(part in SKIPPED_DIR_NAMES for part in relative_parts):
        return True

    return path.name.endswith(GENERATED_SUFFIXES)


def collect_source_files(repo_root: Path, roots: list[Path]) -> list[Path]:
    files: set[Path] = set()

    for root in roots:
        if root.is_file():
            if root.suffix in SOURCE_SUFFIXES and not root.name.endswith(GENERATED_SUFFIXES):
                files.add(root.resolve())
            continue

        for path in root.rglob("*"):
            if path.is_file() and path.suffix in SOURCE_SUFFIXES and not is_skipped(path, repo_root):
                files.add(path.resolve())

    return sorted(files)


def describe_path(repo_root: Path, path: Path) -> str:
    try:
        return str(path.relative_to(repo_root))
    except ValueError:
        return str(path)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Run clang-format over the native sources using the repo .clang-format."
    )
    parser.add_argument(
        "paths",
        nargs="*",
        help="Files or directories to format. Defaults to <repo-root>/src.",
    )
    parser.add_argument(
        "--repo-root",
        help="Path to the repository root. Auto-detected by looking for xmake.lua.",
    )
    parser.add_argument(
        "--clang-format",
        help="Path to clang-format. Defaults to CLANG_FORMAT, then PATH, then the Visual Studio LLVM component.",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Do not modify files; exit with 1 if any file is not formatted.",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="Print every file that is processed.",
    )
    args = parser.parse_args()

    try:
        repo_root = find_repo_root(args.repo_root)
        clang_format = find_clang_format(args.clang_format)
    except FileNotFoundError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2

    if not (repo_root / ".clang-format").is_file():
        print(f"error: .clang-format not found in {repo_root}", file=sys.stderr)
        return 2

    roots = [Path(p).expanduser().resolve() for p in args.paths] or [repo_root / "src"]
    files = collect_source_files(repo_root, roots)

    if not files:
        print("No source files found.")
        return 0

    version = subprocess.run([str(clang_format), "--version"], capture_output=True, text=True, check=False)
    print(f"Using {version.stdout.strip() or clang_format}")

    failed: list[Path] = []
    unformatted: list[Path] = []

    for path in files:
        if args.verbose:
            print(f"  {describe_path(repo_root, path)}")

        if args.check:
            command = [str(clang_format), "--dry-run", "--Werror", "--style=file", str(path)]
        else:
            command = [str(clang_format), "-i", "--style=file", str(path)]

        result = subprocess.run(command, cwd=repo_root, capture_output=True, text=True, check=False)

        if result.returncode == 0:
            continue

        if args.check:
            unformatted.append(path)
        else:
            failed.append(path)
            sys.stderr.write(result.stderr)

    if failed:
        print(f"clang-format failed on {len(failed)} file(s):", file=sys.stderr)
        for path in failed:
            print(f"  {describe_path(repo_root, path)}", file=sys.stderr)
        return 1

    if unformatted:
        print(f"{len(unformatted)} of {len(files)} file(s) need formatting:")
        for path in unformatted:
            print(f"  {describe_path(repo_root, path)}")
        return 1

    print(f"{'Checked' if args.check else 'Formatted'} {len(files)} file(s).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
